"""Conscious: mindful time-tracking CLI.
Usage: python app.py add <task> <minutes> | report [--days N] | reflect
"""
import json, sys, datetime, os

F = os.environ.get('CONSCIOUS_LOG', 'log.json')

def load():
    try:
        with open(F) as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return []

def add(task, minutes, today=None):
    m = int(minutes)
    if m <= 0:
        raise ValueError('minutes must be positive')
    d = load()
    d.append({'d': str(today or datetime.date.today()), 'task': task, 'min': m})
    with open(F, 'w') as f:
        json.dump(d, f)

def totals(days=None, today=None):
    today = today or datetime.date.today()
    s = {}
    for e in load():
        if days is not None and (today - datetime.date.fromisoformat(e['d'])).days >= days:
            continue
        s[e['task']] = s.get(e['task'], 0) + e['min']
    return dict(sorted(s.items(), key=lambda x: -x[1]))

def reflect(days=7):
    t = totals(days)
    if not t:
        return 'No entries yet.'
    tot = sum(t.values()); top = next(iter(t))
    return f'{tot} min logged in {days} days. Top focus: {top} ({100*t[top]//tot}%). Was it intentional?'

def main(a):
    if a and a[0] == 'add' and len(a) == 3:
        add(a[1], a[2])
    elif a and a[0] == 'reflect':
        print(reflect())
    else:
        days = int(a[a.index('--days') + 1]) if '--days' in a else None
        for k, v in totals(days).items():
            print(f'{k}: {v} min')

if __name__ == '__main__':
    main(sys.argv[1:])
