        if days is not None and (today - datetime.date.fromisoformat(e['d'])).days >= days:
            continue
        s[e['task']] = s.get(e['task'], 0) + e['min']
    return dict(sorted(s.items(), key=lambda x: -x[1]))

def reflect(days=7):
    t = totals(days)
    if not t:
        return 'No entries yet.'
    tot = sum(t.values()); top = next(iter(t))
    return f'{tot} min logged in {days} days. Top focus: {top} ({100*t[top]//tot}%). Was it intentional?'

